import{_ as i,C as l,o as t,c as n,a2 as o,b as s,w as r,a as d,E as c,a3 as u}from"./chunks/framework.CCXDMzJr.js";const S=JSON.parse('{"title":"Slicemeter Architecture & Non-Obtrusive Security Model","description":"","frontmatter":{},"headers":[],"relativePath":"guide/security-model.md","filePath":"guide/security-model.md"}'),g={name:"guide/security-model.md"};function m(p,e,h,b,y,f){const a=l("Mermaid");return t(),n("div",null,[e[1]||(e[1]=o('<h1 id="slicemeter-architecture-non-obtrusive-security-model" tabindex="-1">Slicemeter Architecture &amp; Non-Obtrusive Security Model <a class="header-anchor" href="#slicemeter-architecture-non-obtrusive-security-model" aria-label="Permalink to &quot;Slicemeter Architecture &amp; Non-Obtrusive Security Model&quot;">​</a></h1><p>This document outlines the architectural design and security principles of Slicemeter: the GPU FinOps &amp; Token Chargeback engine for Kubernetes.</p><hr><h2 id="_1-core-principles-non-obtrusive-by-default" tabindex="-1">1. Core Principles: Non-Obtrusive by Default <a class="header-anchor" href="#_1-core-principles-non-obtrusive-by-default" aria-label="Permalink to &quot;1. Core Principles: Non-Obtrusive by Default&quot;">​</a></h2><p>Enterprise platforms and Kubernetes security administrators are rightfully cautious regarding cluster-wide mutations and elevated permissions. Slicemeter enforces a strict <strong>non-obtrusive baseline</strong>:</p><ol><li><strong>Zero Workload Mutation Default</strong>: Slicemeter defaults to passive DCGM metric scraping via Prometheus and/or eBPF tracing. It does <strong>NOT</strong> mutate workloads, inject sidecars, or interfere with Pod specs unless explicitly requested.</li><li><strong>Explicit Opt-In Sidecar Injection</strong>:</li></ol><ul><li>The <code>MutatingWebhookConfiguration</code> is <strong>disabled by default</strong> in Helm (<code>webhook.enabled: false</code>).</li><li>Even when enabled, the namespace selector enforces explicit admin labeling (<code>slicemeter.io/injection: enabled</code>).</li><li>Teams can manually annotate workloads (<code>slicemeter.com/inject-sidecar: &quot;true&quot;</code>) without deploying mutating webhooks.</li></ul><ol start="3"><li><strong>Non-Blocking Safety Net</strong>: The admission webhook specifies <code>failurePolicy: Ignore</code> and a strict <code>timeoutSeconds: 5</code>. If the Slicemeter webhook pod is unreachable or failing, Kubernetes <strong>never</strong> blocks Pod creation.</li><li><strong>Least-Privilege RBAC</strong>:</li></ol><ul><li>Slicemeter agent requires <strong>read-only permissions</strong> (<code>get</code>, <code>list</code>, <code>watch</code>) across Nodes, Pods, and Namespaces.</li><li>Zero <code>ClusterAdmin</code> or write capabilities are requested in default installs.</li></ul><hr><h2 id="_2-telemetry-architecture-ebpf-fallbacks" tabindex="-1">2. Telemetry Architecture &amp; eBPF Fallbacks <a class="header-anchor" href="#_2-telemetry-architecture-ebpf-fallbacks" aria-label="Permalink to &quot;2. Telemetry Architecture &amp; eBPF Fallbacks&quot;">​</a></h2>',11)),(t(),s(u,null,{default:r(()=>[c(a,{id:"mermaid-70",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20GPUNode%5B%22Kubernetes%20GPU%20Node%22%5D%0A%20%20%20%20%20%20%20%20Pod%5B%22User%20AI%20Workload%20Pod%22%5D%0A%20%20%20%20%20%20%20%20Agent%5B%22Slicemeter%20Node%20Agent%20DS%22%5D%0A%20%20%20%20%20%20%20%20CudaLib%5B%22libcudart.so%20%2F%20libcuda.so%22%5D%0A%20%20%20%20%20%20%20%20%0A%20%20%20%20%20%20%20%20Pod%20--%3E%7CCUDA%20Calls%7C%20CudaLib%0A%20%20%20%20%20%20%20%20Agent%20--%3E%7CAttach%20Uprobes%7C%20CudaLib%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20CollectionStorage%5B%22Metrics%20%26%20Storage%20Layer%22%5D%0A%20%20%20%20%20%20%20%20DCGM%5B%22DCGM%20Exporter%22%5D%0A%20%20%20%20%20%20%20%20Ledger%5B%22Agent%20Ledger%20(BadgerDB%2Fetcd)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20ControlPlaneLayer%5B%22Slicemeter%20Control%20Plane%22%5D%0A%20%20%20%20%20%20%20%20API%5B%22Control%20Plane%20API%20Server%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20CudaLib%20--%3E%20DCGM%0A%20%20%20%20Agent%20--%3E%20Ledger%0A%20%20%20%20DCGM%20--%3E%20API%0A%20%20%20%20Ledger%20--%3E%20API%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h3 id="ebpf-precision-mode-vs-dcgm-fallback-mode" tabindex="-1">eBPF Precision Mode vs DCGM Fallback Mode <a class="header-anchor" href="#ebpf-precision-mode-vs-dcgm-fallback-mode" aria-label="Permalink to &quot;eBPF Precision Mode vs DCGM Fallback Mode&quot;">​</a></h3><ul><li><strong>DCGM Fallback Mode (Default)</strong>: Reads cluster metrics passively via Prometheus. Requires zero kernel dependencies and zero elevated Linux capabilities. Works 100% out of the box across <strong>Azure AKS</strong>, <strong>AWS EKS</strong>, <strong>Google Cloud GKE</strong>, and self-managed Kubernetes.</li><li><strong>eBPF Precision Mode (Opt-In)</strong>: Attaches uprobes to <code>libcudart.so</code> / <code>libcuda.so</code> on Linux kernel 5.8+ with <code>CAP_BPF</code> &amp; <code>CAP_PERFMON</code>. Attributes sub-second CUDA kernel execution directly to host PIDs and Kubernetes cgroups.</li></ul><h3 id="multi-cloud-os-driver-resolution" tabindex="-1">Multi-Cloud OS &amp; Driver Resolution <a class="header-anchor" href="#multi-cloud-os-driver-resolution" aria-label="Permalink to &quot;Multi-Cloud OS &amp; Driver Resolution&quot;">​</a></h3><p>Slicemeter automatically adapts to multi-cloud driver locations and OS file layouts:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Cloud Provider</th><th style="text-align:left;">Node OS / Driver Layout</th><th style="text-align:left;">Driver Library Path Resolution</th><th style="text-align:left;">Collector Fallback</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Azure AKS</strong></td><td style="text-align:left;">Ubuntu / Azure Linux</td><td style="text-align:left;"><code>/usr/lib/x86_64-linux-gnu/libcuda.so</code></td><td style="text-align:left;">DCGM &amp; PromQL <code>avg by (kubernetes_node)</code></td></tr><tr><td style="text-align:left;"><strong>AWS EKS</strong></td><td style="text-align:left;">Amazon Linux 2 / Bottlerocket</td><td style="text-align:left;"><code>/usr/lib64/libcudart.so</code></td><td style="text-align:left;">DCGM &amp; PromQL <code>avg by (node, instance)</code></td></tr><tr><td style="text-align:left;"><strong>GCP GKE</strong></td><td style="text-align:left;">Container-Optimized OS (COS)</td><td style="text-align:left;"><code>/usr/local/nvidia/lib64/libcuda.so</code></td><td style="text-align:left;">DCGM &amp; PromQL <code>avg by (hostname)</code></td></tr></tbody></table><hr><h2 id="_3-storage-layer-embedded-badgerdb-distributed-etcd" tabindex="-1">3. Storage Layer: Embedded BadgerDB &amp; Distributed etcd <a class="header-anchor" href="#_3-storage-layer-embedded-badgerdb-distributed-etcd" aria-label="Permalink to &quot;3. Storage Layer: Embedded BadgerDB &amp; Distributed etcd&quot;">​</a></h2><p>Slicemeter supports dual ledger backends depending on deployment topology:</p><ul><li><strong>Embedded BadgerDB (<code>SLICEMETER_LEDGER_BACKEND=badger</code>)</strong>: Zero external state dependencies. Stores transaction logs directly inside the agent Pod persistent volume. Ideal for edge clusters, single-node setups, and managed Kubernetes (EKS/GKE/AKS).</li><li><strong>Distributed etcd (<code>SLICEMETER_LEDGER_BACKEND=etcd</code>)</strong>: Uses standard etcd storage for HA multi-agent deployments on self-managed clusters.</li></ul><hr><h2 id="_4-hardened-security-isolation-model" tabindex="-1">4. Hardened Security &amp; Isolation Model <a class="header-anchor" href="#_4-hardened-security-isolation-model" aria-label="Permalink to &quot;4. Hardened Security &amp; Isolation Model&quot;">​</a></h2><p>Slicemeter enforces a zero-trust, non-obtrusive security posture across all Kubernetes deployments:</p><h3 id="minimal-read-only-rbac-boundaries" tabindex="-1">Minimal Read-Only RBAC Boundaries <a class="header-anchor" href="#minimal-read-only-rbac-boundaries" aria-label="Permalink to &quot;Minimal Read-Only RBAC Boundaries&quot;">​</a></h3><ul><li><strong>Zero Workload Mutation</strong>: Slicemeter ServiceAccounts hold strictly read-only cluster permissions.</li><li><strong>Isolated API Groups</strong>: The agent cannot create, modify, or delete workload Pods, Deployments, or StatefulSets (<code>apps/v1</code>, <code>core/v1</code>).</li></ul><h3 id="network-egress-lockdown" tabindex="-1">Network Egress Lockdown <a class="header-anchor" href="#network-egress-lockdown" aria-label="Permalink to &quot;Network Egress Lockdown&quot;">​</a></h3><ul><li><strong>Egress Isolation</strong>: Enforces a strict <code>NetworkPolicy</code> restricting agent network egress strictly to the cluster API server and local Prometheus endpoints.</li><li><strong>Zero Internet Egress in Air-Gap</strong>: No external phone-home calls, analytics pings, or license validation requests leave your infrastructure boundary.</li></ul><h3 id="cryptographic-tls-cert-bootstrapping" tabindex="-1">Cryptographic TLS Cert Bootstrapping <a class="header-anchor" href="#cryptographic-tls-cert-bootstrapping" aria-label="Permalink to &quot;Cryptographic TLS Cert Bootstrapping&quot;">​</a></h3><ul><li><strong>ECDSA P-256 TLS Encryption</strong>: Automated in-cluster ECDSA P-256 certificate generation for all admission and telemetry endpoints.</li><li><strong>Dependency-Free Security</strong>: Eliminates external cert-manager or secret injector dependencies.</li></ul><h3 id="fail-safe-admission-webhook-guarantee" tabindex="-1">Fail-Safe Admission Webhook Guarantee <a class="header-anchor" href="#fail-safe-admission-webhook-guarantee" aria-label="Permalink to &quot;Fail-Safe Admission Webhook Guarantee&quot;">​</a></h3><ul><li><strong>Availability First</strong>: Configured with <code>failurePolicy: Ignore</code> to guarantee that API server availability and pod scheduling are never blocked, even if telemetry collection experiences temporary network degradation.</li></ul><hr><h2 id="_5-multi-tenant-enterprise-single-sign-on-sso-oidc" tabindex="-1">5. Multi-Tenant Enterprise Single Sign-On (SSO &amp; OIDC) <a class="header-anchor" href="#_5-multi-tenant-enterprise-single-sign-on-sso-oidc" aria-label="Permalink to &quot;5. Multi-Tenant Enterprise Single Sign-On (SSO &amp; OIDC)&quot;">​</a></h2><p>Slicemeter Control Plane provides enterprise-grade identity federation across both hosted SaaS (<code>app.slicemeter.com</code>) and air-gapped on-premise deployments:</p><h3 id="standard-public-saas-auth-app-slicemeter-com" tabindex="-1">Standard Public SaaS Auth (<code>app.slicemeter.com</code>) <a class="header-anchor" href="#standard-public-saas-auth-app-slicemeter-com" aria-label="Permalink to &quot;Standard Public SaaS Auth (`app.slicemeter.com`)&quot;">​</a></h3><ul><li><strong>Developer &amp; Starter Access</strong>: Work email/password authentication or 1-click <strong>GitHub OAuth 2.0</strong>.</li><li><strong>Domain Auto-Routing</strong>: Enterprise organizations register their corporate domain (<code>company.com</code>). When employees log in via <code>company.com</code>, Slicemeter automatically redirects them to their corporate identity provider.</li></ul><h3 id="self-hosted-enterprise-on-premise-auth" tabindex="-1">Self-Hosted Enterprise On-Premise Auth <a class="header-anchor" href="#self-hosted-enterprise-on-premise-auth" aria-label="Permalink to &quot;Self-Hosted Enterprise On-Premise Auth&quot;">​</a></h3><ul><li><strong>OIDC &amp; SAML 2.0 Protocol Support</strong>: Native integration with Microsoft Entra ID (Azure AD), Okta, Keycloak, Ping Identity, and Auth0.</li><li><strong>Zero-Trust Identity Mapping</strong>: Maps corporate IdP SAML assertion claims (<code>groups</code>, <code>roles</code>) directly to Slicemeter RBAC roles (<code>admin</code>, <code>finops</code>, <code>viewer</code>).</li></ul>',27))])}const P=i(g,[["render",m]]);export{S as __pageData,P as default};
